function(container, apiUrl, tables) {
  // テーブルインデックス
  const storeTableIndex = tables.findIndex(t => t.tableName === '店舗マスタ');
  const productTableIndex = tables.findIndex(t => t.tableName === '商品マスタ');
  const predictionTableIndex = tables.findIndex(t => t.tableName === '需要予測結果');
  const salesTableIndex = tables.findIndex(t => t.tableName === '売上実績データ');

  // DOM要素取得
  const storeSelect = container.querySelector('#store-select');
  const categorySelect = container.querySelector('#category-select');
  const startDate = container.querySelector('#start-date');
  const endDate = container.querySelector('#end-date');
  const modelSelect = container.querySelector('#model-select');
  const btnPredict = container.querySelector('#btn-predict');
  const predictionStatus = container.querySelector('#prediction-status');
  const predictionResults = container.querySelector('#prediction-results');
  const errorMessage = container.querySelector('#error-message');
  const productsTableBody = container.querySelector('#products-tbody');
  const progressBar = container.querySelector('#progress-bar');

  // 初期日付設定
  const today = new Date();
  const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  startDate.value = today.toISOString().split('T')[0];
  endDate.value = nextWeek.toISOString().split('T')[0];

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
    setTimeout(() => {
      errorMessage.classList.add('hidden');
    }, 5000);
  }

  // バリデーション関数
  function validateInputs() {
    if (!storeSelect.value) {
      showError('店舗を選択してください');
      return false;
    }
    if (!categorySelect.value) {
      showError('商品カテゴリを選択してください');
      return false;
    }
    if (!startDate.value) {
      showError('予測期間の開始日を設定してください');
      return false;
    }
    if (!endDate.value) {
      showError('予測期間の終了日を設定してください');
      return false;
    }
    if (!modelSelect.value) {
      showError('予測モデルを選択してください');
      return false;
    }

    const start = new Date(startDate.value);
    const end = new Date(endDate.value);
    const now = new Date();
    now.setHours(0, 0, 0, 0);

    if (start < now) {
      showError('開始日は現在日以降の日付を設定してください');
      return false;
    }

    if (start >= end) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    return true;
  }

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(storeTableIndex);
    if (stores) {
      stores.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品別予測一覧の再描画
  function renderProductPredictions(predictions) {
    if (!predictions || predictions.length === 0) {
      productsTableBody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">予測データがありません</td></tr>';
      return;
    }

    productsTableBody.innerHTML = predictions.map(pred => `
      <tr data-id="${pred.予測結果ID}">
        <td>${pred.商品コード || 'N/A'}</td>
        <td>${pred.商品名 || 'N/A'}</td>
        <td>${pred.予測対象日 ? new Date(pred.予測対象日).toLocaleDateString() : 'N/A'}</td>
        <td style="text-align: right;">${pred.予測数量 ? pred.予測数量.toLocaleString() : 0}</td>
        <td style="text-align: right;">${pred.予測精度 || 0}%</td>
        <td style="text-align: right;">${pred.推奨発注数量 ? pred.推奨発注数量.toLocaleString() : 0}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${pred.予測結果ID}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // グラフ描画関数
  function drawPredictionChart() {
    const canvas = container.querySelector('#prediction-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const dates = [];
    const actualData = [];
    const predictedData = [];

    for (let i = 0; i < 14; i++) {
      const date = new Date();
      date.setDate(date.getDate() + i);
      dates.push(date.getDate());
      actualData.push(Math.floor(Math.random() * 50) + 100);
      predictedData.push(Math.floor(Math.random() * 40) + 110);
    }

    const padding = 50;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const maxValue = Math.max(...actualData, ...predictedData) * 1.1;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 実績データ線
    ctx.strokeStyle = '#4CAF50';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i / (actualData.length - 1)) * chartWidth;
      const y = canvas.height - padding - (actualData[i] / maxValue) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測データ線
    ctx.strokeStyle = '#2196F3';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = padding + (i / (predictedData.length - 1)) * chartWidth;
      const y = canvas.height - padding - (predictedData[i] / maxValue) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.setLineDash([]);

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px Arial';
    ctx.fillText('実績', padding, 20);
    ctx.fillStyle = '#4CAF50';
    ctx.fillRect(padding + 30, 12, 15, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('予測', padding + 80, 20);
    ctx.fillStyle = '#2196F3';
    ctx.fillRect(padding + 110, 12, 15, 3);
  }

  // 比較チャート描画
  function drawComparisonChart() {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const categories = ['食品', '飲料', '日用品', '衣料品'];
    const actual = [120, 85, 95, 110];
    const predicted = [115, 90, 88, 105];

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const barWidth = chartWidth / (categories.length * 2.5);
    const maxValue = Math.max(...actual, ...predicted) * 1.2;

    // 軸
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // バー描画
    categories.forEach((category, i) => {
      const x = padding + (i * chartWidth / categories.length) + barWidth / 2;

      // 実績バー
      const actualHeight = (actual[i] / maxValue) * chartHeight;
      ctx.fillStyle = '#4CAF50';
      ctx.fillRect(x, canvas.height - padding - actualHeight, barWidth, actualHeight);

      // 予測バー
      const predictedHeight = (predicted[i] / maxValue) * chartHeight;
      ctx.fillStyle = '#2196F3';
      ctx.fillRect(x + barWidth + 5, canvas.height - padding - predictedHeight, barWidth, predictedHeight);

      // カテゴリ名
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(category, x + barWidth / 2, canvas.height - padding + 20);
    });
  }

  // 予測実行処理
  async function executePrediction() {
    if (!validateInputs()) return;

    // UI状態更新
    btnPredict.disabled = true;
    predictionStatus.classList.remove('hidden');
    predictionResults.classList.add('hidden');

    // プログレスバーアニメーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 90) progress = 90;
      progressBar.style.width = progress + '%';
    }, 200);

    try {
      // 予測結果データ作成
      const predictionData = {
        店舗ID: storeSelect.value,
        商品ID: 'sample-product-id',
        予測対象日: startDate.value,
        予測数量: Math.floor(Math.random() * 200) + 100,
        予測精度: Math.floor(Math.random() * 20) + 80,
        推奨発注数量: Math.floor(Math.random() * 150) + 80,
        予測モデルバージョン: modelSelect.value,
        予測ステータス: '完了',
        発注済フラグ: false,
        備考: 'AI予測実行による自動生成'
      };

      // 予測結果保存
      await window.aivicApi.save(predictionTableIndex, predictionData);

      // 完了処理
      setTimeout(() => {
        clearInterval(progressInterval);
        progressBar.style.width = '100%';

        setTimeout(() => {
          predictionStatus.classList.add('hidden');
          predictionResults.classList.remove('hidden');
          btnPredict.disabled = false;

          // グラフ描画
          drawPredictionChart();
          drawComparisonChart();

          // 商品別予測一覧更新
          loadPredictionResults();
        }, 500);
      }, 2000);

    } catch (error) {
      clearInterval(progressInterval);
      predictionStatus.classList.add('hidden');
      btnPredict.disabled = false;
      showError('予測処理中にエラーが発生しました');
    }
  }

  // 予測結果読み込み
  async function loadPredictionResults() {
    const predictions = await window.aivicApi.list(predictionTableIndex);
    if (predictions) {
      // 商品情報を結合
      const products = await window.aivicApi.list(productTableIndex);
      const enrichedPredictions = predictions.map(pred => {
        const product = products?.find(p => p.商品ID === pred.商品ID);
        return {
          ...pred,
          商品コード: product?.商品コード,
          商品名: product?.商品名
        };
      });
      renderProductPredictions(enrichedPredictions);
    }
  }

  // CSVエクスポート
  function exportToCsv() {
    window.aivicApi.list(predictionTableIndex).then(predictions => {
      if (!predictions || predictions.length === 0) {
        showError('エクスポートするデータがありません');
        return;
      }

      const headers = ['予測結果ID', '店舗ID', '商品ID', '予測対象日', '予測数量', '予測精度', '推奨発注数量', '予測ステータス'];
      const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
        predictions.map(row => headers.map(h => `"${row[h] || ''}"`).join(',')).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 商品検索
  function searchProducts() {
    const keyword = container.querySelector('#product-search').value.toLowerCase();
    window.aivicApi.list(predictionTableIndex).then(predictions => {
      if (predictions) {
        const filtered = predictions.filter(pred => 
          JSON.stringify(pred).toLowerCase().includes(keyword)
        );
        renderProductPredictions(filtered);
      }
    });
  }

  // イベントリスナー設定
  btnPredict.addEventListener('click', executePrediction);

  container.querySelector('#btn-export').addEventListener('click', exportToCsv);

  container.querySelector('#btn-refresh').addEventListener('click', loadPredictionResults);

  container.querySelector('#btn-product-search').addEventListener('click', searchProducts);

  container.querySelector('#product-search').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') searchProducts();
  });

  // 行レベル操作
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const predictionId = detailBtn.dataset.id;
      // 詳細画面への遷移（実装時は適切な画面IDに変更）
      window.showScreen('scr-1778591885672'); // AI需要予測処理画面
    }
  });

  // 初期データ読み込み
  loadStores();
  loadPredictionResults();
}
